/**
 * Homepage hero data. The hero shows one thing okmodel does that a query
 * builder cannot: you edit `schema.ts`, and the planner writes the safe
 * migration, the linter says what to look at, and the types move with it.
 *
 * Each scenario is a one-line edit to the same small schema. What the hero
 * shows for it (the diff, the plan, the lint findings, the type change) is the
 * output of the real `okm generate` and `okm build`, regenerated by
 * `scripts/hero-derived.ts` and gated by `hero-derived.site-test.ts`. Only the
 * labels and the one-line notes are written by hand.
 */

import derivedJson from "./hero-derived.json";
import { HERO_QUERIES, type HeroQuerySpec } from "./hero-queries";
import type { HeroDiffRow, HeroGroupId, HeroScenarioId } from "./hero-types";

export type { HeroDiffMark, HeroDiffRow, HeroGroupId, HeroScenarioId } from "./hero-types";

/** Groups in tab order. */
export const HERO_GROUPS: ReadonlyArray<{ readonly id: HeroGroupId; readonly label: string }> = [
  { id: "migrate", label: "Migrate" },
  { id: "model", label: "Model" },
  { id: "query", label: "Query" },
];

/** The schema every scenario edits. It is the first migration. */
export const HERO_BASE_SCHEMA = `import { schema, table, t } from "okmodel/pg";

const authors = table("authors", {
  id: t.identity(),
  name: t.text(),
});

const notes = table("notes", {
  id: t.identity(),
  title: t.text().nullable(),
  authorId: t.bigint(),
});

export default schema({ tables: [authors, notes] });
`;

/** A schema with no tables, for a scenario that starts a new app. */
const HERO_EMPTY_SCHEMA = `import { schema } from "okmodel/pg";

export default schema({ tables: [] });
`;

/** One text replacement applied to {@link HERO_BASE_SCHEMA}. `find` must occur exactly once. */
export interface HeroEdit {
  readonly find: string;
  readonly replace: string;
}

/** A schema edit as written by hand: what to edit, and what to call it. */
export interface HeroMigrateSpec {
  readonly kind: "migrate";
  readonly id: HeroScenarioId;
  /** Tab group. */
  readonly group: HeroGroupId;
  /** Tab label. */
  readonly label: string;
  /** Name given to `okm generate`, so the file is `0002_<name>.sql`. */
  readonly name: string;
  /** One sentence for the foot rail. It describes what the panels show. */
  readonly note: string;
  /** Handbook page for the part of the schema the edit touches. */
  readonly href: string;
  /** Schema the edit applies to. Defaults to {@link HERO_BASE_SCHEMA}. */
  readonly base?: string;
  readonly edits: ReadonlyArray<HeroEdit>;
}

