/** One statement of a generated migration, with the header the file gives it. */
export interface HeroStep {
  readonly class: "expand" | "contract";
  /** Planner kind, such as `validate-constraint`. */
  readonly kind: string;
  /** Locks the statement takes. */
  readonly lock: string;
  /** False when the statement cannot run in a transaction. */
  readonly transactional: boolean;
  readonly sql: string;
}

/** One finding the linter printed for the generated file. */
export interface HeroFinding {
  readonly severity: "error" | "warning";
  readonly code: string;
  readonly step: number;
  readonly message: string;
  readonly fix: string;
}

/** What `okm generate` and `okm build` produced for one schema edit. */
export interface HeroDerivedMigrate {
  readonly kind: "migrate";
  readonly id: HeroScenarioId;
  /** The schema edit, as a diff with context. */
  readonly diff: ReadonlyArray<HeroDiffRow>;
  readonly plan: {
    readonly file: string;
    readonly class: "expand" | "contract";
    readonly steps: ReadonlyArray<HeroStep>;
  };
  readonly lint: ReadonlyArray<HeroFinding>;
  /** The first change in `.okm/types.d.ts`, or `null` when the types did not move. */
  readonly types: {
    readonly label: string;
    readonly rows: ReadonlyArray<HeroDiffRow>;
    /** Changed lines past the ones shown. */
    readonly more: number;
  } | null;
}

/** One rule the planner recorded for a statement, from `inspect()`. */
export interface HeroRule {
  readonly rule: string;
  readonly contribution: string;
  /** Who asked for it: the `caller`, the `planner`, or the `catalog`. */
  readonly provenance: string;
}

/** An OkmError the call threw, recorded from the run. */
export interface HeroQueryError {
  readonly code: string;
  readonly message: string;
  readonly fix: string;
}

/** What the client produced when the query really ran on PGlite. */
export interface HeroDerivedQuery {
  readonly kind: "query";
  readonly id: HeroScenarioId;
  /** The model lines and then the query, as shown on the left. */
  readonly code: ReadonlyArray<HeroDiffRow>;
  readonly sql: {
    /** The statement, split at its top-level clauses. Empty when the call was refused. */
    readonly text: string;
    readonly params: ReadonlyArray<string>;
  };
  readonly result: {
    /** The value the call returned, as text. For a refuse, the error text. */
    readonly text: string;
    /** Rows returned, when the call returns a list. */
    readonly count: number | null;
  };
  readonly rules: ReadonlyArray<HeroRule>;
  /** Present when a call threw before or instead of a successful statement. */
  readonly error: HeroQueryError | null;
}

/** The generated output for one scenario. */
export type HeroDerived = HeroDerivedMigrate | HeroDerivedQuery;

/** A migrate scenario ready to show: the hand-written spec and the real output. */
export interface HeroMigrateScenario extends HeroMigrateSpec, Omit<HeroDerivedMigrate, "id" | "kind"> {}

/** A query scenario ready to show. */
export interface HeroQueryScenario extends HeroQuerySpec, Omit<HeroDerivedQuery, "id" | "kind"> {}

/** A scenario ready to show. */
export type HeroScenario = HeroMigrateScenario | HeroQueryScenario;

/** Every scenario spec, in walk order: one group after the other. */
export function heroSpecs(): ReadonlyArray<HeroMigrateSpec | HeroQuerySpec> {
  return HERO_GROUPS.flatMap((group) => [
    ...HERO_SCENARIOS.filter((spec) => spec.group === group.id),
    ...HERO_QUERIES.filter((spec) => spec.group === group.id),
  ]);
}

/**
 * Join the hand-written specs to what the tooling produced for them.
 *
 * @param derived - Output of `scripts/hero-derived.ts`
 */
export function heroScenarios(derived: ReadonlyArray<HeroDerived>): ReadonlyArray<HeroScenario> {
  return heroSpecs().map((spec): HeroScenario => {
    const found = derived.find((item) => item.id === spec.id);
    if (found === undefined || found.kind !== spec.kind) {
      throw new Error(`hero-derived.json has no ${spec.kind} scenario ${spec.id}`);
    }
    const { id: _id, kind: _kind, ...rest } = found;
    return { ...spec, ...rest } as HeroScenario;
  });
}

/**
 * A scenario's base schema with its edits applied.
 *
 * @param spec - Scenario to apply
 */
export function applyEdits(spec: HeroMigrateSpec): string {
  let source = spec.base ?? HERO_BASE_SCHEMA;
  for (const edit of spec.edits) {
    const first = source.indexOf(edit.find);
    if (first < 0 || source.indexOf(edit.find, first + 1) >= 0) {
      throw new Error(`${spec.id}: edit must match exactly once: ${edit.find}`);
    }
    source = source.replace(edit.find, () => edit.replace);
  }
  return source;
}

/**
 * Scenarios with their real output, read from the checked-in file. A function,
 * not a constant, so `scripts/hero-derived.ts` can import this module while the
 * file is being regenerated.
 */
export function shownScenarios(): ReadonlyArray<HeroScenario> {
  return heroScenarios((derivedJson as { scenarios: ReadonlyArray<HeroDerived> }).scenarios);
}

/** Package contract cells for the foot rail. The version is appended by the caller. */
export const HERO_CONTRACT: ReadonlyArray<string> = [
  "PostgreSQL 15–18",
  "Apache-2.0",
];
